17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
20	import org.springframework.stereotype.Component;
21	import org.springframework.validation.Errors;
22	import org.springframework.validation.ValidationUtils;
23	import org.springframework.validation.Validator;
24	
25	/**
26	 * Validates an {@link OwnerFieldsDto} as part of the {@code @Valid} pass on the owner
27	 * request body: the address is canonicalised and then, like the other required text fields,
28	 * required to be present and non-blank; the telephone is canonicalised to E.164 form and
29	 * required to be a valid such number; and an optional email is required to be syntactically
30	 * valid and normalized to lower case.
31	 * <p>
32	 * Registered on the owner controller through {@code @InitBinder} so every rejected field is
33	 * recorded as a field error on the shared {@link Errors}, surfacing through the usual
34	 * bad-request handling. The canonical address and a valid telephone (in E.164 form) are
35	 * written back to the DTO so they are stored, returned and compared for duplicates as those
36	 * canonical strings.
37	 *
38	 * @author Vitaliy Fedoriv
39	 */
40	@Component
41	public class OwnerFieldsValidator implements Validator {
42	
43	    private static final String[] REQUIRED_FIELDS = {"firstName", "lastName", "address", "city", "telephone"};
44	
45	    private final TelephoneNormalizer telephoneNormalizer;
46	
47	    private final EmailNormalizer emailNormalizer;
48	
49	    private final AddressNormalizer addressNormalizer;
50	
51	    public OwnerFieldsValidator(TelephoneNormalizer telephoneNormalizer, EmailNormalizer emailNormalizer,
52	                                AddressNormalizer addressNormalizer) {
53	        this.telephoneNormalizer = telephoneNormalizer;
54	        this.emailNormalizer = emailNormalizer;
55	        this.addressNormalizer = addressNormalizer;
56	    }
57	
58	    @Override
59	    public boolean supports(Class<?> clazz) {
60	        return OwnerFieldsDto.class.isAssignableFrom(clazz);
61	    }
62	
63	    @Override
64	    public void validate(Object target, Errors errors) {
65	        OwnerFieldsDto owner = (OwnerFieldsDto) target;
66	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
67	        for (String field : REQUIRED_FIELDS) {
68	            ValidationUtils.rejectIfEmptyOrWhitespace(errors, field, "required", "must not be blank");
69	        }
70	        if (!errors.hasFieldErrors("telephone")) {
71	            normalizeTelephone(owner, errors);
72	        }
73	        normalizeEmail(owner, errors);
74	    }
75	
76	    private void normalizeTelephone(OwnerFieldsDto owner, Errors errors) {
77	        telephoneNormalizer.toE164(owner.getTelephone()).ifPresentOrElse(
78	            owner::setTelephone,
79	            () -> errors.rejectValue("telephone", "telephone.invalid",
80	                "must be a valid telephone number in E.164 form"));
81	    }
82	
83	    private void normalizeEmail(OwnerFieldsDto owner, Errors errors) {
84	        String email = owner.getEmail();
85	        if (email == null) {
86	            return;
87	        }
88	        if (emailNormalizer.isValid(email)) {
89	            owner.setEmail(emailNormalizer.normalize(email));
90	        } else {
91	            errors.rejectValue("email", "email.invalid", "must be a valid email address");
92	        }
93	    }
94	}
